package net.minecraft.network.chat; import net.minecraft.ChatFormatting; public class Component { public String value; public Component(String v){value=v;} public static Component literal(String v){return new Component(v);} public Component withStyle(ChatFormatting style){return this;} public Component append(Component v){value+=v.value;return this;} public String getString(){return value;} public String toString(){return value;}}